namespace MyApp.Evals.Tests;

internal static class Thresholds
{
    private static readonly Lazy<ThresholdConfig> s_config = new(() =>
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return new ThresholdConfig();
        var options = new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower, PropertyNameCaseInsensitive = true };
        return JsonSerializer.Deserialize<ThresholdConfig>(File.ReadAllText(path), options) ?? new();
    });

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        var config = s_config.Value;
        if (!config.HardFail) return;

        foreach (var metric in result.Metrics)
        {
            if (config.Thresholds.TryGetValue(metric.Key, out var threshold))
            {
                if (metric.Value is NumericMetric nm && threshold.MinValue.HasValue)
                {
                    if (nm.Value < threshold.MinValue.Value)
                        Assert.Fail($"[{scenarioId}] {metric.Key} = {nm.Value} below threshold {threshold.MinValue}");
                }
            }
        }
    }
}

internal record ThresholdConfig
{
    public bool HardFail { get; init; }
    public Dictionary<string, ThresholdEntry> Thresholds { get; init; } = new();
}

internal record ThresholdEntry
{
    public double? MinValue { get; init; }
    public double? MaxValue { get; init; }
    public string? MinRating { get; init; }
}

