// Mirror the AppHost registration: AddAzureChatCompletionsClient("chat").AddChatClient("chat")
// This requires the Aspire.Azure.AI.Inference package. Since the eval project
// runs standalone (outside the AppHost), we build an equivalent IChatClient from config.
builder.Services.AddSingleton<IChatClient>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var connectionString = config.GetConnectionString("chat")
        ?? throw new InvalidOperationException("ConnectionStrings:chat is not configured.");
    // Parse connection string to build the client
    var parts = connectionString.Split(';')
        .Select(p => p.Split('=', 2))
        .Where(p => p.Length == 2)
        .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);
    parts.TryGetValue("Endpoint", out var endpoint);
    parts.TryGetValue("Key", out var key);
    parts.TryGetValue("DeploymentId", out var deploymentId);
    if (string.IsNullOrEmpty(endpoint))
        throw new InvalidOperationException("ConnectionStrings:chat must contain an Endpoint.");

    var credential = string.IsNullOrEmpty(key)
        ? (object)new Azure.Identity.DefaultAzureCredential()
        : new Azure.AzureKeyCredential(key);
    var clientOptions = new Azure.AI.Inference.ChatCompletionsClientOptions();
    var client = credential is Azure.AzureKeyCredential keyCredential
        ? new Azure.AI.Inference.ChatCompletionsClient(new Uri(endpoint), keyCredential, clientOptions)
        : new Azure.AI.Inference.ChatCompletionsClient(new Uri(endpoint), (Azure.Core.TokenCredential)credential, clientOptions);
    return client.AsChatClient(deploymentId ?? "chat");
});

